# ---------- spec parsing ----------
FN_REFS = []  # global list of (fn_name, line) in order encountered during parsing of a script

def _find_bracket_end(s, idx):
    # idx at '['
    j = s.find(']', idx+1)
    return j

def _scan_spec_token(s, start):
    """scan a token until un-bracketed whitespace. Return (token, end_index)"""
    i=start
    depth=0
    while i < len(s):
        c=s[i]
        if c=='[':
            depth+=1; i+=1; continue
        if c==']':
            if depth>0: depth-=1
            i+=1; continue
        if depth==0 and c in ' \t':
            break
        i+=1
    return s[start:i], i

def _parse_choice_content(content, line):
    # content inside []
    if content.startswith('='):
        data=content[1:].split('|')
        if len(data) < 2:
            raise ParseError(f"syntax error at line {line}")
        return Choice("Values", data), Default("Value", data[0])
    if content.startswith('?`') and content.endswith('`') and len(content)>=4:
        fn=content[2:-1]
        if not fn or '`' in fn:
            raise ParseError(f"syntax error at line {line}")
        return Choice("Fn", [fn, False]), None
    if content.startswith('`') and content.endswith('`') and len(content)>=2:
        fn=content[1:-1]
        if not fn:
            raise ParseError(f"syntax error at line {line}")
        return Choice("Fn", [fn, True]), None
    if content.startswith('`') or content.startswith('?`'):
        # malformed fn bracket
        raise ParseError(f"syntax error at line {line}")
    data=content.split('|')
    return Choice("Values", data), None

def _parse_default_value(rest, line):
    """rest is string after '=' up to token end"""
    if rest.startswith('`'):
        nxt = rest.find('`',1)
        if nxt != -1:
            if nxt != len(rest)-1:
                raise ParseError(f"syntax error at line {line}")
            fn = rest[1:-1]
            if not fn:
                # `` treated as value
                return Default("Value", rest)
            return Default("Fn", fn)
        else:
            return Default("Value", rest)
    else:
        return Default("Value", rest)

class SuffixResult:
    def __init__(self):
        self.required=False
        self.multiple=False
        self.delimiter=None
        self.terminated=False
        self.assigned=False
        self.prefixed=False
        self.default=None
        self.choice=None

def _parse_suffix(token, idx, line, kind):
    """Parse suffix starting at idx in token. kind: flag/option/arg/env
       Returns SuffixResult"""
    res=SuffixResult()
    seen=set()
    i=idx
    while i < len(token):
        c=token[i]
        if c=='!':
            if res.required or res.multiple:
                raise ParseError(f"syntax error at line {line}")
            res.required=True; i+=1
        elif c=='*':
            if res.multiple or res.terminated:
                raise ParseError(f"syntax error at line {line}")
            res.multiple=True; i+=1
        elif c=='+':
            if res.required or res.multiple or res.terminated:
                raise ParseError(f"syntax error at line {line}")
            res.required=True; res.multiple=True; i+=1
        elif c==',':
            if not res.multiple or res.delimiter is not None:
                raise ParseError(f"syntax error at line {line}")
            res.delimiter=","; i+=1
        elif c=='~':
            if res.multiple or res.terminated:
                raise ParseError(f"syntax error at line {line}")
            res.terminated=True; res.multiple=True; i+=1
        elif c==':':
            if res.assigned:
                raise ParseError(f"syntax error at line {line}")
            res.assigned=True; i+=1
        elif c=='=':
            i+=1
            rest=token[i:]
            res.default=_parse_default_value(rest, line)
            i=len(token)
        elif c=='[':
            j=_find_bracket_end(token, i)
            if j==-1:
                raise ParseError(f"syntax error at line {line}")
            content=token[i+1:j]
            choice, dft = _parse_choice_content(content, line)
            res.choice=choice
            if dft is not None:
                res.default=dft
            i=j+1
            if i != len(token):
                raise ParseError(f"syntax error at line {line}")
        else:
            raise ParseError(f"syntax error at line {line}")
    # kind-specific validation
    if kind=='flag':
        # flags only allow * and : (assigned) and prefixed (handled before)
        if res.required or res.terminated or res.delimiter is not None or res.default is not None or res.choice is not None:
            raise ParseError(f"syntax error at line {line}")
    if kind=='env':
        if res.multiple or res.terminated:
            # will be converted by caller to specific message; store marker
            res._env_invalid=True  # type: ignore
        if res.delimiter is not None:
            # delimiter without multiple already syntax; with multiple is env invalid
            pass
    return res

def _process_trailing_name(segment, token_prefix_len):
    """Handle trailing '-' / ':' markers on name segment. Return (clean_segment, prefixed, assigned)"""
    prefixed=False; assigned=False
    seg=segment
    # process up to two trailing markers
    for _ in range(3):
        if not seg:
            break
        if seg[-1]=='-':
            stripped=seg[:-1]
            if stripped and stripped[-1]=='-':
                seg=stripped; prefixed=False; break
            else:
                seg=stripped; prefixed=True; continue
        elif seg[-1]==':':
            stripped=seg[:-1]
            if stripped and stripped[-1]==':':
                seg=stripped; assigned=False; break
            else:
                seg=stripped; assigned=True; continue
        else:
            break
    return seg, prefixed, assigned

_NAME_CHARS=set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_@.:")
def _parse_name_token(token, line, kind):
    """kind flag/option. Returns dict with id,long_name,short_name etc and suffix result"""
    if not token or token[0] not in '-+':
        raise ParseError(f"syntax error at line {line}")
    # prefix length
    if token.startswith('--') and len(token)>2 and token[2]!='-':
        prefix_len=2; sign='-'
    elif token.startswith('--') and len(token)==2:
        prefix_len=2; sign='-'
    else:
        prefix_len=1; sign=token[0]
    i=prefix_len
    start=i
    while i < len(token) and token[i] in _NAME_CHARS:
        i+=1
    segment=token[start:i]
    # segment may be empty (e.g. token '--' -> prefix_len 2 segment '' ; special handling ; original long='-' prefixed True)
    clean_seg, t_prefixed, t_assigned = _process_trailing_name(segment, prefix_len)
    # But if clean seg differs, the characters consumed includes those markers, ok.
    # If segment was processed, no change to i.
    suffix=_parse_suffix(token, i, line, kind)
    # merge trailing markers
    prefixed = t_prefixed or suffix.prefixed
    assigned = t_assigned or suffix.assigned
    # For token '--' : segment '-'? wait prefix_len2 -> segment '' ; token[?] Let's handle special: if token=='--', segment should be '-' before prefix processing.
    if token=='--':
        clean_seg=''; prefixed=True
        long_name='-'
        id_=''
    else:
        # long_name is token up to suffix start (i) but with trailing markers stripped in segment portion
        # reconstruct: sign-prefix part = token[:prefix_len] ??? original long construction: token[:i] with segment replaced by clean_seg
        long_name = token[:prefix_len] + clean_seg if not (prefix_len==2) else token[:prefix_len] + clean_seg
