def _record_fn_ref(fn, line):
    FN_REFS.append((fn, line))

def _parse_arg_tag(body, line_no, cur):
    if not body:
        raise ParseError(f"syntax error at line {line_no}")
    token, end_idx = _scan_spec_token(body, 0)
    if not token:
        raise ParseError(f"syntax error at line {line_no}")
    # token parse for positional: name segment + suffix
    # name: consume until suffix chars !*+,~=[  (':' etc included)
    i=0
    while i < len(token) and token[i] not in '!*+,~=[':
        i+=1
    name_seg = token[:i]
    if not name_seg or name_seg.startswith('='):
        raise ParseError(f"syntax error at line {line_no}")
    # suffix parse by constructing suffix string token[i:]
    # Use _parse_suffix on token with idx i but _parse_suffix expects full token; it works.
    suffix = _parse_suffix(token, i, line_no, 'arg')
    # duplicate check
    if name_seg in cur._arg_map:
        old_line = cur._arg_map[name_seg]
        raise ParseError(f"@arg(line {line_no}) has '{name_seg}' already exists at line {old_line}")
    cur._arg_map[name_seg]=line_no
    # fn refs
    if suffix.choice and suffix.choice.type=='Fn':
        _record_fn_ref(suffix.choice.data[0], line_no)
    if suffix.default and suffix.default.type=='Fn':
        _record_fn_ref(suffix.default.value, line_no)
    pos = Positional()
    pos.id=name_seg; pos.line=line_no
    pos.required=suffix.required; pos.multiple=suffix.multiple; pos.delimiter=suffix.delimiter; pos.terminated=suffix.terminated
    pos.default=suffix.default; pos.choice=suffix.choice
    pos.notation=name_seg.upper()
    # remainder after token
    pos_idx = end_idx
    pos_idx = _skip_spaces(body, pos_idx)
    # env binder
    try:
        env_name, new_pos, consumed = _parse_env_binder(body, pos_idx, name_seg)
    except ParseError as e:
        # patch line number
        raise ParseError(f"syntax error at line {line_no}")
    if consumed:
        pos.env=env_name; pos_idx=new_pos; pos_idx=_skip_spaces(body, pos_idx)
    # notation
    if pos_idx < len(body) and body[pos_idx]=='<':
        gt = body.find('>', pos_idx+1)
        if gt!=-1:
            # must be followed by space/end
            if gt+1 < len(body) and body[gt+1] not in ' \t':
                raise ParseError(f"syntax error at line {line_no}")
            pos.notation=body[pos_idx+1:gt]
            pos_idx=gt+1; pos_idx=_skip_spaces(body, pos_idx)
