# ---------- help rendering ----------
def get_term_width():
    v=os.environ.get('TERM_WIDTH')
    if v is None: return None
    try:
        return int(v)
    except:
        return None

def wrap_text(text, width, indent_first=0, indent_rest=0):
    """Wrap a single line (no \n) to width, indent_first/rest are counts for prefix lengths? Returns list of strings without trailing spaces.
       Original wrapping preserves words, breaks at spaces. If width is None, return [text]"""
    if width is None:
        return [text]
    if text=="":
        return [""]
    # implement greedy wrap like textwrap: available width is width - indent (per line)
    words=text.split(' ')
    # Need to preserve multiple consecutive spaces? Original likely collapses? Descriptions have single spaces mostly. Preserve by splitting? We'll use word split handling empty tokens.
    lines=[]
    cur=None
    cur_indent=indent_first
    for w in words:
        if cur is None:
            cur=w; continue
        if len(cur)+1+len(w) + cur_indent <= width:
            cur+=" "+w
        else:
            lines.append(cur)
            cur_indent=indent_rest
            cur=w
    if cur is not None:
        lines.append(cur)
    return lines

def render_describe_block(describe, width):
    if not describe:
        return ""
    out_lines=[]
    for raw_line in describe.split('\n'):
        wrapped=wrap_text(raw_line, width, 0,0)
        out_lines.extend(wrapped)
    return "\n".join(out_lines)

