    if fo.assigned:
        # first notation
        notn=fo.notations[0] if fo.notations else fo.id.upper()
        return f"{long_name}=<{notn}>"
    if len(fo.notations)>1 or (fo.notations and fo.notations[0] and any(fo.notations[0].endswith(x) for x in []) ):
