        return f"{long_name} {base}"
    # single notation
    notn=fo.notations[0] if fo.notations else fo.id.upper()
    # If notation contains modifier like VALUE*, VALUE+, VALUE?, OXA~ - render as <NOTATION>
    if notn.endswith(('*','+','?','~')) and len(fo.notations)==1 and (fo.num_args[1]==32767 or fo.num_args[0]==0) and not fo.multiple_occurs:
