            if desc:
                for raw_desc_line in desc.split('\n'):
                    wrapped=wrap_text(raw_desc_line, width, 10,10) if width else [raw_desc_line]
                    for wl in wrapped:
                        lines.append(" "*10+wl if wl!="" else "")
            if idx != len(items)-1:
                lines.append("")
