        if not items:
            return ""
        max_len=max(len(h) for h,_ in items)
        col=max_len+2
        for header,desc in items:
            if not desc:
                lines.append(header)
            else:
                # wrap description: first line at col, rest at col
                # desc may contain \n? in non-stacked, desc shouldn't contain \n (stacked trigger). But just in case flatten?
