                desc_lines=[]
                for raw in desc.split('\n'):
                    if width:
                        wrapped=wrap_text(raw, width, col, col)
                    else:
                        wrapped=[raw]
                    desc_lines.extend(wrapped)
                # first
                lines.append(header + " "*(col-len(header)) + desc_lines[0] if desc_lines else header)
