    required_opts=[]
    for o in user_opts:
        if o.required:
            required_opts.append(o)
        else:
            has_nonrequired_user=True
    if has_nonrequired_user:
        parts.append("[OPTIONS]")
    for o in required_opts:
        parts.append(param_render_name_for_option(o))
    if cmd.subcommands:
        parts.append("<COMMAND>")
    else:
        for p in pos_list:
