            header="  "+sub.name
            desc_first=(sub.describe.split('\n')[0] if sub.describe else "")
            annotations=[]
            if sub.aliases:
                annotations.append(f"[aliases: {', '.join(sub.aliases)}]")
            if sub.default_subcommand_meta_line is not None or (sub.metadata and 'default-subcommand' in sub.metadata):
