            desc_text=desc_first
            if annotations:
                if desc_text:
                    desc_text=desc_text+" "+" ".join(annotations)
                else:
                    desc_text=" ".join(annotations)
            items.append((header,desc_text))
        # commands section is never stacked
        blocks.append("COMMANDS:\n"+render_list_section(items, width, False))
