    if cmd.envs:
        stacked=any('\n' in (e.describe or '') for e in cmd.envs)
        items=[]
        for e in cmd.envs:
            name=e.id + ("*" if e.required else "")
            header="  "+name
            desc=annotate_describe(e,'env') if not stacked else (e.describe or '')
            items.append((header,desc))
        blocks.append("ENVIRONMENTS:\n"+render_list_section(items, width, stacked))
    text="\n\n".join(blocks)+"\n"
    return text

