        cause=f"{os.strerror(e.errno)} (os error {e.errno})" if e.errno else str(e)
        stderr_write(f"Failed to create Argcfile.sh\n\nCaused by:\n    {cause}\n"); return 1
    stdout_write("Argcfile.sh has been successfully created.\n"); return 0

def do_script_path(argv):
    p=find_argcfile()
    if p is None:
        stderr_write("Argcfile not found.\n"); return 1
    stdout_write(p+"\n"); return 0
def do_shell_path(argv):
    try:
        shell, _ = get_shell_path()
    except ValueError as e:
        stderr_write(str(e)+"\n"); return 1
    stdout_write(shell+"\n"); return 0

# placeholders to be filled later
def do_build(argv):
    stderr_write("No script file provided\n") if not argv else stderr_write("build not implemented\n")
    return 1 if not argv else 1
def do_mangen(argv):
    if not argv:
        stderr_write("No script file provided\n"); return 1
    if len(argv)<2:
        stderr_write("No output dir\n"); return 1
    return 1
def do_completions(argv):
    if not argv:
        stderr_write("Usage: argc --argc-completions <SHELL> [CMDS]...\n"); return 1
    shell=argv[0]
    if shell not in ("bash","elvish","fish","nushell","powershell","xonsh","zsh","tcsh"):
        stderr_write("The provided shell is either invalid or missing, must be one of bash,elvish,fish,nushell,powershell,xonsh,zsh,tcsh\n"); return 1
    stdout_write(get_completion_script(shell, argv[1:])); return 0
def do_compgen(argv):
    return compgen_main(argv)
def do_parallel(argv):
    if len(argv)<2:
        stderr_write("Usage: argc --argc-parallel <SCRIPT> <ARGS>...\n"); return 1
    script=argv[0]; rest=argv[1:]
    try:
        shell, from_env = get_shell_path()
    except ValueError as e:
        stderr_write(str(e)+"\n"); return 1
    try:
        text=load_script(script)
    except LoadError as e:
        stderr_write(e.msg()); return 1
    if "--argc-eval" not in text:
        stderr_write("Parallel only available for argc based scripts.\n"); return 1
    # split groups by :::
    groups=[]; cur=[]
    for tok in rest:
        if tok==":::":
            groups.append(cur); cur=[]
        else:
            cur.append(tok)
    groups.append(cur)
    # run each in parallel capturing stdout/stderr
    procs=[]
    env=dict(os.environ); env['ARGC_PARALLEL']='1'
    for g in groups:
        if not g: continue
        cmd=[]
        if from_env:
            cmd=[shell, script, "___parallel___"]+g
        else:
            cmd=[shell, "--noprofile", "--norc", script, "___parallel___"]+g
        try:
            p=subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
        except Exception as e:
            stderr_write(str(e)+"\n"); return 1
        procs.append(p)
    any_fail=False
    outputs=[]
    for p in procs:
        out,err=p.communicate()
        outputs.append((out,err))
        if p.returncode!=0: any_fail=True
    for out,err in outputs:
        if out: sys.stdout.buffer.write(out)
    for out,err in outputs:
        if err: sys.stderr.buffer.write(err)
    return 1 if any_fail else 0

def main(argv):
    if not argv:
        return do_run([], is_runner=True, runner_args=[])
    first=argv[0]
    if first.startswith("--argc-"):
        disp={
            "--argc-eval": do_eval,
            "--argc-create": do_create,
            "--argc-run": lambda a: do_run(a, is_runner=False),
            "--argc-build": do_build,
            "--argc-mangen": do_mangen,
            "--argc-completions": do_completions,
            "--argc-compgen": do_compgen,
            "--argc-export": do_export,
            "--argc-parallel": do_parallel,
            "--argc-script-path": do_script_path,
            "--argc-shell-path": do_shell_path,
        }
        if first=="--argc-help":
            stdout_write(ARGC_HELP); return 0
        if first=="--argc-version":
            stdout_write(f"argc {VERSION}\n"); return 0
        if first in disp:
            return disp[first](argv[1:])
        else:
            stderr_write(f"Unknown option `{first}`\n"); return 1
    else:
        return do_run([], is_runner=True, runner_args=argv)

if __name__=="__main__":
    sys.exit(main(sys.argv[1:]))

