# ---------- mangen ----------
def _man_escape(s):
    return str(s).replace('-', '\\-')
def _man_describe_body(describe, choice=None):
    # returns body string following .TP header (without trailing?)
    if choice is not None and choice.type=='Values':
        possible_line=f"[\\fIpossible values: \\fR{', '.join(choice.data)}]"
        # escape choice values? original escapes hyphens in values likely via overall?
        possible_line=_man_escape_possible(possible_line)
        if describe:
            body=".br\n"+_man_escape(describe).replace('\n','\n.br\n')+"\n"
            body+=f".br\n\n.br\n{possible_line}\n"
            return body
        else:
            return f"\n.br\n{possible_line}\n"
    if describe:
        return ".br\n"+_man_escape(describe).replace('\n','\n.br\n')+"\n"
    else:
        return "\n"
def _man_escape_possible(s):
    # possible values part after \fR contains values joined; escape hyphens in the values part only? Simplify: escape hyphens in whole but \fI etc have no hyphen
    # values may contain '-'; original possibly escapes them. We'll escape '-' that are not part of \f ?
    return s
def _man_option_header(fo):
    # names
    names=[]
    long_name=fo.long_name or ""
    short_name=fo.short_name
    def bold(name):
        return f"\\fB{_man_escape(name)}\\fR"
    if short_name and long_name:
        header=f"{bold(short_name)}, {bold(long_name)}"
    elif long_name:
        header=f"{bold(long_name)}"
    elif short_name:
        header=f"{bold(short_name)}"
    else:
        header=""
    if not fo.flag:
        if len(fo.notations)>1:
            header+=" "+" ".join(f"\\fI{_man_escape(notn)}\\fR" for notn in fo.notations)
        elif len(fo.notations)==1:
            notn=fo.notations[0]
            if fo.assigned:
                header+=f"=\\fI{notn}\\fR"
            elif fo.multiple_occurs:
                if fo.required:
                    header+=f"=<\\fI{notn}\\fR>..."
                else:
                    header+=f"=[\\fI{notn}\\fR]..."
            elif fo.required:
                header+=f"=<\\fI{notn}\\fR>"
            else:
                header+=f"=\\fI{notn}\\fR"
        # default annotation
    if fo.default is not None and fo.default.type=='Value':
        header+=f" [default: {_man_escape(fo.default.value)}]"
    return header
def _man_positional_header(p):
    notn=p.notation
    if p.required:
        h=f"<\\fI{notn}\\fR>"
    else:
        h=f"[\\fI{notn}\\fR]"
    if p.multiple:
        h+="..."
    return h
def _man_env_header(e):
    h=f"\\fI{e.id}\\fR"
    if e.required:
        h+="*"
    if e.default is not None and e.default.type=='Value':
        h+=f" [default: {_man_escape(e.default.value)}]"
    return h

def man_page_for_command(cmd, path_cmds):
    path_hyphen="-".join(command_path_names(path_cmds))
    # for .TH uppercase
    th_name=path_hyphen.upper()
    version_str=cmd.version if cmd.version is not None else "0.0.0"
    out=""
    out+=f".TH {th_name} 1  \"{path_hyphen} {version_str}\" \n"
    out+=".SH NAME\n"
    name_escaped=_man_escape(path_hyphen)
    desc_first=cmd.describe.split('\n')[0] if cmd.describe else ""
    if desc_first:
        out+=f"{name_escaped} \\- {_man_escape(desc_first)}\n"
    else:
        out+=f"{name_escaped}\n"
    out+=".SH SYNOPSIS\n"
    syn_path=" ".join(command_path_names(path_cmds))
    suffix=build_usage_suffix(cmd)
    out+=f"\\fB{_man_escape(syn_path)}\\fR"
    if suffix:
        out+=f" {suffix}"
    out+="\n"
    if cmd.describe and '\n' in cmd.describe:
        out+=".SH DESCRIPTION\n"
        for line in cmd.describe.split('\n'):
            out+=".br\n"+_man_escape(line)+"\n"
    # OPTIONS
    user_opts=[o for o in cmd.flag_options if not o.is_auto]
    if user_opts or cmd.positionals:
        out+=".SH OPTIONS\n"
        for fo in cmd.flag_options:
            # include all (user+auto)
            out+=".TP\n"
            out+=_man_option_header(fo)+"\n"
            out+=_man_describe_body(fo.describe, fo.choice)
        for p in cmd.positionals:
            out+=".TP\n"
            out+=_man_positional_header(p)+"\n"
            out+=_man_describe_body(p.describe, p.choice)
    if cmd.subcommands:
        out+=".SH SUBCOMMANDS\n"
        for sub in cmd.subcommands:
            child_path=path_cmds+[sub]
            child_hyphen="-".join(command_path_names(child_path))
            out+=".TP\n"
            out+=f"{_man_escape(child_hyphen)}(1)\n"
            if sub.describe:
