# ---------- compgen ----------
class Candidate:
    def __init__(self, value, display, description, kind, space=True):
        self.value=value; self.display=display; self.description=description or ""; self.kind=kind; self.space=space

def _truncate_desc(desc):
    first=desc.split('\n')[0] if desc else ""
    if len(first)>83:
        return first[:83]+"..."
    return first

def _choice_values_for_compgen(state, root, choice, prog, words_with_current, current_word, script_path):
    if choice is None: return []
    if choice.type=='Values':
        return list(choice.data)
    if choice.type=='Fn':
        fn=choice.data[0]
        # spawn
        # Determine ARGC_CWORD: passed by caller via state? We'll use a global context stored in state object
        cword=getattr(state,'compgen_cword', current_word)
        extra={'ARGC_COMPGEN':'1','ARGC_CWORD':cword,'ARGC_LAST_ARG':current_word}
        saved_prog=state.prog; saved_args=state.user_args; saved_script=state.script_path
        # get_choice_values uses state.prog/script_path and args list (words)
        vals=get_choice_values(state, fn, list(words_with_current), extra_env=extra)
        if vals is None:
            return []
        return vals
    return []

def _file_candidates(current, dir_only=False):
    # current is prefix string for file path
    # split dir part
    if '/' in current:
        dir_part, file_prefix = current.rsplit('/',1)
        dir_part_incl=dir_part+'/'
        list_dir=dir_part if dir_part else '/'
    else:
        dir_part_incl=''; file_prefix=current; list_dir='.'
    try:
        entries=os.listdir(list_dir)
    except Exception:
        return []
    entries_sorted=sorted(entries)
    out=[]
    for name in entries_sorted:
        if not name.startswith(file_prefix): continue
        if not file_prefix.startswith('.') and name.startswith('.'): continue
        full_path=os.path.join(list_dir, name) if list_dir!='.' else name
        # for candidate type determination, need actual path relative to cwd: if list_dir is '.' then name; else if dir part is /tmp etc use os.path.join
        is_dir=os.path.isdir(full_path)
        if dir_only and not is_dir: continue
        value=dir_part_incl+name+('/' if is_dir else '')
        display=name+('/' if is_dir else '')
        if is_dir:
            kind='dir'; space=False
        elif os.path.isfile(full_path) and os.access(full_path, os.X_OK):
            kind='executable'; space=True
        else:
            kind='file'; space=True
        out.append(Candidate(value, display, "", kind, space))
    return out

def _notation_file_kind(notation):
    if notation is None: return None
    up=notation.upper()
    if 'FILE' in up or 'PATH' in up or 'TARGET' in up:
        return 'all'
    if 'DIR' in up or 'FOLDER' in up:
        return 'dirs'
    return None

def _candidates_for_param_value(state, root, param, is_positional, current, prog, words_with_current, script_path, value_index=0):
    # param is FlagOption or Positional
    # Determine choices
    choice=getattr(param,'choice',None)
    # Determine prefix base for delimiter / etc handled by caller? We'll handle delimiter inside here using current
    delim=getattr(param,'delimiter',None)
    if delim and delim in current:
        prefix_part, partial = current.rsplit(delim,1)
        base=prefix_part+delim
        used=set(prefix_part.split(delim)) if prefix_part else set()
        if choice:
            vals=_choice_values_for_compgen(state, root, choice, prog, words_with_current, current, script_path)
            out=[]
            for v in vals:
                if v in used: continue
                if not v.startswith(partial): continue
                out.append(Candidate(base+v, v, "", 'value', False))
            return out
        else:
            # file heuristic based on notation
            notation=_param_notation_for_index(param, value_index)
            fk=_notation_file_kind(notation)
            if fk:
                files=_file_candidates(partial, dir_only=(fk=='dirs'))
                out=[]
                for fc in files:
                    out.append(Candidate(base+fc.value, fc.display, "", fc.kind, False))
                return out
            return []
    # non-delimiter
    if choice:
        vals=_choice_values_for_compgen(state, root, choice, prog, words_with_current, current, script_path)
