def _get_pending_option(state, seg):
    if seg is None: return None
    p=seg.last_param
    if p is None or getattr(p,'flag',True): return None
    if getattr(p,'assigned',False): return None
    occs=seg.occurrences.get(id(p), [])
    if not occs: return None
    occ=occs[-1]
    if occ.via_eq: return None
    # max per occurrence
    if getattr(p,'terminated',False):
        maxv=10**9
    elif p.multiple_occurs:
        maxv=1
    else:
        maxv=p.num_args[1] if p.num_args else 1
    if len(occ.values) < maxv:
        return (p, occ)
    return None

def _next_positional_def(state, seg):
    if seg is None: return None, None
    cmd=seg.cmd
    if not cmd.positionals:
        return None, None
    # cursor logic: iterate previous raw positionals
    idx=0
    raw=seg.raw_positionals
    # We need to simulate assignment: For each def, if single, one token moves to next; if multiple, stays.
    # But raw tokens count may exceed singles etc.
    pos_idx=0
    consumed=0
    # Simpler: walk defs
    for token_i in range(len(raw)):
        if pos_idx>=len(cmd.positionals): break
        p=cmd.positionals[pos_idx]
        if p.multiple:
            # stays on this def
            continue
        else:
            pos_idx+=1
    if pos_idx>=len(cmd.positionals):
        return None, None
    return cmd.positionals[pos_idx], pos_idx

