def _format_candidates(shell, cands, current):
    if not cands:
        return ""
    out=[]
    if shell=='bash':
        if len(cands)==1:
            c=cands[0]
            out.append(c.value + (" " if c.space else "") + "\n")
        else:
            # LCP
            vals=[c.value for c in cands]
            lcp=os.path.commonprefix(vals)
            if len(lcp) > len(current):
                out.append(lcp+"\n")
            else:
                for c in cands:
                    if c.description:
                        out.append(f"{c.display} ({c.description})\n")
                    else:
                        out.append(f"{c.display}" + (" " if c.space else "") + "\n")
        return "".join(out)
    elif shell=='fish':
        for c in cands:
            if c.description: out.append(f"{c.value}\t{c.description}\n")
            else: out.append(f"{c.value}\n")
        return "".join(out)
    elif shell=='nushell':
        for c in cands:
            sp=" " if c.space else ""
            if c.description: out.append(f"{c.value}{sp}\t{c.description}\n")
            else: out.append(f"{c.value}{sp}\n")
        return "".join(out)
    elif shell=='zsh':
        for c in cands:
            sp=" " if c.space else ""
            disp=f"{c.display}:{c.description}" if c.description else c.display
            code=_color_for_kind(c.kind, True)
            out.append(f"{c.value}{sp}\t{disp}\t{c.display}\t{code}\n")
        return "".join(out)
    elif shell=='elvish':
        for c in cands:
            code=_color_for_kind(c.kind, False)
            out.append(f"{c.value}\t{1 if c.space else 0}\t{c.display}\t{c.description}\t{code}\n")
        return "".join(out)
    elif shell=='powershell':
        for c in cands:
            code=_color_for_kind(c.kind, True)
            out.append(f"{c.value}\t{1 if c.space else 0}\t{c.display}\t{c.description}\t{code}\n")
        return "".join(out)
    elif shell=='xonsh':
        for c in cands:
            out.append(f"{c.value}\t{1 if c.space else 0}\t{c.display}\t{c.description}\n")
        return "".join(out)
    elif shell=='tcsh':
        if len(cands)==1:
            c=cands[0]; out.append(f"{c.value}\n")
        else:
            braille='⠀'
            for c in cands:
                if c.description:
                    desc=c.description.replace(' ', braille)
                    out.append(f"{c.display}{braille}({desc})\n")
                else:
                    out.append(f"{c.display}\n")
        return "".join(out)
    return ""
