    if width is None:
        return [text]
    if text=="":
        return [""]
    words=text.split(' ')
    # optimal-fit DP (textwrap-like): minimize sum of squared slack for non-last lines, trailing space counted for non-last lines
    from functools import lru_cache
    n=len(words)
    # Precompute content lengths for segments
    def seg_len(i,j, first):
        indent=indent_first if first else indent_rest
        return indent + len(' '.join(words[i:j]))
    def best(i, first):
        # returns (cost, list_of_segments_end_indices)
        if i>=n:
            return (0, [])
        best_cost=None; best_segs=None
        # try j from i+1 upwards (earliest break first for ties)
        for j in range(i+1, n+1):
            is_last=(j==n)
            eff=seg_len(i,j,first) + (0 if is_last else 1)
            if eff>width and j>i+1:
                # longer segments only get worse; but a segment with one word may overflow
                # if this segment already exceeds, further j will also exceed (length increases), so break
                break
            if eff>width and j==i+1:
                # single word overflow allowed
                cost_rest, segs_rest = best(j, False) if not is_last else (0, [])
                cost = (10000 + (eff-width)*(eff-width)) + cost_rest
                if best_cost is None or cost < best_cost:
                    best_cost=cost; best_segs=[j]+segs_rest
                continue
            if is_last:
                cost=0
                segs=[]
            else:
                cost_rest, segs_rest = best(j, False)
                slack=width-eff
                cost = slack*slack + cost_rest
                segs=segs_rest
            total=cost
            if best_cost is None or total < best_cost:
                best_cost=total; best_segs=[j]+segs
        if best_segs is None:
            return (0, [n])
        return (best_cost, best_segs)
    _, segs = best(0, True)
    lines=[]; prev=0
    for end_idx in segs:
        lines.append(' '.join(words[prev:end_idx])); prev=end_idx
    if prev<n:
        lines.append(' '.join(words[prev:]))
    return lines

'''
